   async fn record_finished_game_inner(app: &App, match_id: &str, finished: Option<Finished>, seats: &(MatchSeat, MatchSeat)) -> Result<Option<GameRecord>, String> {
       let mut tx = app.db.begin(None).await.map_err(message_of)?;
       let mode = match &finished { None => None, Some(_) => tx.matches_mode_of(match_id).await.map_err(message_of)? };
       let (finished, mode) = match (finished, mode) {
           (Some(finished), Some(mode)) => (finished, mode),
           (finished, _) => {
               tx.commit().await.map_err(message_of)?;
               skipped(match_id, finished.is_some());
               return Ok(None);
           }
       };
       let profiles = tx.profiles_get_many(&[seats.0.profile_id.clone(), seats.1.profile_id.clone()]).await.map_err(message_of)?;
       tx.commit().await.map_err(message_of)?;
       let Finished { row, log, folded } = finished;
       let folded = folded?;
       // R677, R1451: each seat under the account the result credits it to, so after a Glitch's swap a bot's `ai` goes on the seat it ended in, with no fold to read the swap.
